// Gisela, Blade of Goldnight
// status: ready
// Flying, first strike
// If a source would deal damage to an opponent or a permanent an opponent controls, that source deals double that damage to that player or permanent instead.
// If a source would deal damage to you or a permanent you control, prevent half that damage, rounded up.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_2_applies(q: &dyn Query, asker: &Asker, proposal: &Proposal) -> bool { if let Proposal::Damage(e) = proposal { let (source, target, amount, combat) = (e.source, &e.target, e.amount, e.combat); let subject = *target; let data = [u32::from(amount), source.0]; if true && true && match *target { Target::Object(o) => (Some(asker.controller).into_iter().flat_map(|p: PlayerId| q.state().opponents(p)).collect::<Vec<PlayerId>>()).contains(&q.controller(o)), Target::Player(p) => (Some(asker.controller).into_iter().flat_map(|p: PlayerId| q.state().opponents(p)).collect::<Vec<PlayerId>>()).contains(&p), _ => false } { return true; } }
 false }
#[allow(unused_variables, unused_mut)] fn ability_2_apply(q: &dyn Query, asker: &Asker, proposal: &mut Proposal) { let seen = *proposal; if let Proposal::Damage(seen) = &seen { let e = seen; let (source, target, amount, combat) = (e.source, &e.target, e.amount, e.combat); let subject = *target; let data = [u32::from(amount), source.0]; if let Proposal::Damage(e) = proposal { e.amount = ((2i64 * i64::from(data[0]))).min(u16::MAX.into()) as u16; } } }
#[allow(unused_variables)] fn ability_3_applies(q: &dyn Query, asker: &Asker, e: &cantrip_api::DamageEvent) -> bool { { let (source, target, amount, combat) = (e.source, &e.target, e.amount, e.combat); let subject = *target; let data = [u32::from(amount), source.0]; if true && true && match *target { Target::Object(o) => Some(asker.controller) == Some(q.controller(o)), Target::Player(p) => Some(asker.controller) == Some(p), _ => false } { return true; } }
 false }
#[allow(unused_variables)] fn ability_3_amount(q: &dyn Query, asker: &Asker, e: &cantrip_api::DamageEvent) -> u16 { let (source, target, amount, combat) = (e.source, &e.target, e.amount, e.combat); let subject = *target; let data = [u32::from(amount), source.0]; ((i64::from(data[0])).saturating_add(1).div_euclid(2)).min(u16::MAX.into()) as u16 }

